CREATE POLICY "notification_email_audit" ON "audit_entries" AS PERMISSIVE FOR INSERT TO "sep_runtime" WITH CHECK ("audit_entries"."organization_id" = nullif(current_setting('sep.organization_id', true), '')::uuid AND "audit_entries"."person_id" = nullif(current_setting('sep.person_id', true), '')::uuid AND "audit_entries"."event_id" IS NULL AND "audit_entries"."action"='identity.notification-email.updated' AND "audit_entries"."resource_id"="audit_entries"."person_id");